SELECT 'batch_012_1408f656_wav_10' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-03470670-934','sm-upload-374b472d-1d7','sm-upload-5b301238-460','sm-upload-690ad431-b59','sm-upload-6d9de5af-539','sm-upload-748d72b1-fc1','sm-upload-9bf8a3dc-49c','sm-upload-a4759b23-456','sm-upload-d178378d-bc5','sm-upload-f55d9ac5-408') AND album_id='al-513e3da59502f103e5112f7b1408f656') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-03470670-934','sm-upload-374b472d-1d7','sm-upload-5b301238-460','sm-upload-690ad431-b59','sm-upload-6d9de5af-539','sm-upload-748d72b1-fc1','sm-upload-9bf8a3dc-49c','sm-upload-a4759b23-456','sm-upload-d178378d-bc5','sm-upload-f55d9ac5-408') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-513e3da59502f103e5112f7b1408f656' AND name='幽灵摄影') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-513e3da59502f103e5112f7b1408f656') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-513e3da59502f103e5112f7b1408f656') AS calculated_size;
